/** JUnit regression coverage for PGM-08-E01 routing spaces, overlap guards and atomic allocations. */
final class IpamApplicationServiceTest{private static final Clock CLOCK=Clock.fixed(Instant.parse("2026-08-15T16:30:00Z"),ZoneOffset.UTC);@Test void fullLifecycle(){var repo=new Repo();var idem=new Idem();var events=new InMemoryEventStore();var ids=new UuidV7Generator(CLOCK,new SecureRandom(new byte[]{8,3,0,1}));var org=ids.next();var sub=ids.next();var site=ids.next();var rsot=ids.next();var equipment=ids.next();var actor=ids.next();var corr=ids.next();var svc=new IpamApplicationService(repo,idem,new Features(true),new Refs(org,sub,site,rsot,equipment),events,ids,CLOCK);var ctx=new IpamCommandContext(actor,corr,"govern IPAM allocation","ipam-smoke-0001");
 var vrf=svc.createVrf(new CreateVrfCommand(org,"PROD","Production","65000:1"),ctx);vrf=svc.changeVrfStatus(vrf.id(),1,IpamStatus.ACTIVE,new IpamCommandContext(actor,corr,"activate VRF","ipam-smoke-0002"));var vlan=svc.createVlan(new CreateVlanCommand(org,site,120,null,"Application"),new IpamCommandContext(actor,corr,"create VLAN","ipam-smoke-0003"));vlan=svc.changeVlanStatus(vlan.id(),1,IpamStatus.ACTIVE,new IpamCommandContext(actor,corr,"activate VLAN","ipam-smoke-0004"));final IpamVrf activeVrf=vrf;final IpamVlan activeVlan=vlan;
 var net=svc.createNetwork(new CreateNetworkCommand(org,sub,site,activeVrf.id(),activeVlan.id(),null,NetworkKind.SUBNET,"10.20.30.0/24","applications","trusted"),new IpamCommandContext(actor,corr,"create subnet","ipam-smoke-0005"));net=svc.changeNetworkStatus(net.id(),1,IpamStatus.ACTIVE,new IpamCommandContext(actor,corr,"activate subnet","ipam-smoke-0006"));final IpamNetwork activeNet=net;expect("DDI_CIDR_OVERLAP",()->svc.createNetwork(new CreateNetworkCommand(org,sub,site,activeVrf.id(),activeVlan.id(),null,NetworkKind.SUBNET,"10.20.30.128/25",null,null),new IpamCommandContext(actor,corr,"overlap","ipam-smoke-0007")));
 var pool=svc.createPool(new CreatePoolCommand(org,activeNet.id(),"10.20.30.10","10.20.30.12","dynamic"),new IpamCommandContext(actor,corr,"create pool","ipam-smoke-0008"));var a1=svc.allocate(new AllocateAddressCommand(org,activeVrf.id(),activeNet.id(),pool.id(),null,false,"app01",rsot,equipment,"primary"),new IpamCommandContext(actor,corr,"allocate address","ipam-smoke-0009"));require("10.20.30.10".equals(a1.address()),"first automatic allocation");var a2=svc.allocate(new AllocateAddressCommand(org,activeVrf.id(),activeNet.id(),pool.id(),"10.20.30.12",true,null,null,null,"reserved"),new IpamCommandContext(actor,corr,"reserve address","ipam-smoke-0010"));require(a2.status()==AddressStatus.RESERVED,"reservation state");var page1=svc.addresses(org,activeVrf.id(),activeNet.id(),null,1);require(page1.items().size()==1&&page1.nextCursor()!=null,"address cursor first page");var page2=svc.addresses(org,activeVrf.id(),activeNet.id(),page1.nextCursor(),1);require(page2.items().size()==1&&page2.nextCursor()==null,"address cursor second page");expect("DDI_ADDRESS_CONFLICT",()->svc.allocate(new AllocateAddressCommand(org,activeVrf.id(),activeNet.id(),pool.id(),"10.20.30.12",false,null,null,null,null),new IpamCommandContext(actor,corr,"duplicate","ipam-smoke-0011")));var released=svc.release(a1.id(),1,new IpamCommandContext(actor,corr,"release address","ipam-smoke-0012"));require(released.status()==AddressStatus.RELEASED,"release");var updated=svc.updateNetwork(activeNet.id(),2,new UpdateNetworkCommand(activeVlan.id(),"application tier","trusted"),new IpamCommandContext(actor,corr,"update metadata","ipam-smoke-0013"));require("application tier".equals(updated.usage()),"network update");expect("DDI_VLAN_IN_USE",()->svc.changeVlanStatus(activeVlan.id(),2,IpamStatus.RETIRED,new IpamCommandContext(actor,corr,"retire used vlan","ipam-smoke-0014")));require(repo.routingLocks>0&&repo.poolLocks>0,"allocation locks exercised");require(events.outboxSnapshot().stream().anyMatch(x->"ddi.ipam.address.allocated.v1".equals(x.event().eventType().value())),"allocation event");var disabled=new IpamApplicationService(repo,idem,new Features(false),new Refs(org,sub,site,rsot,equipment),events,ids,CLOCK);expect("DDI_IPAM_CAPABILITY_UNAVAILABLE",()->disabled.vrfs(org,10));}
 @Test void errorReplayQuotaAndTerminalBranches(){
  var repo=new Repo();var idem=new Idem();var events=new InMemoryEventStore();var ids=new UuidV7Generator(CLOCK,new SecureRandom(new byte[]{4,4,4,4}));
  var org=ids.next();var sub=ids.next();var site=ids.next();var rsot=ids.next();var equipment=ids.next();var actor=ids.next();var corr=ids.next();
  IpamFeaturePolicy limits=new IpamFeaturePolicy(){public boolean ipamEnabled(){return true;}public long vrfLimit(){return 1;}public long vlanLimit(){return 2;}public long prefixLimit(){return 3;}public long addressLimit(){return 2;}};
  var svc=new IpamApplicationService(repo,idem,limits,new Refs(org,sub,site,rsot,equipment),events,ids,CLOCK);
  var vrfCtx=new IpamCommandContext(actor,corr,"create routing environment","ipam-edge-0001");
  var vrf=svc.createVrf(new CreateVrfCommand(org,"EDGE","Edge",null),vrfCtx);
  require(vrf.id().equals(svc.createVrf(new CreateVrfCommand(org,"EDGE","Edge",null),vrfCtx).id()),"VRF idempotency replay");
  expect("IDEMPOTENCY_CONFLICT",()->svc.createVrf(new CreateVrfCommand(org,"OTHER","Other",null),vrfCtx));
  expect("DDI_VRF_QUOTA",()->svc.createVrf(new CreateVrfCommand(org,"EXTRA","Extra",null),new IpamCommandContext(actor,corr,"quota","ipam-edge-0002")));
  var activeVrf=svc.changeVrfStatus(vrf.id(),1,IpamStatus.ACTIVE,new IpamCommandContext(actor,corr,"activate routing environment","ipam-edge-0003"));
  expect("DDI_VRF_TRANSITION",()->svc.changeVrfStatus(activeVrf.id(),2,IpamStatus.DRAFT,new IpamCommandContext(actor,corr,"invalid transition","ipam-edge-0004")));

  var vlan=svc.createVlan(new CreateVlanCommand(org,site,200,9000L,"edge"),new IpamCommandContext(actor,corr,"create segment","ipam-edge-0005"));
  expect("DDI_VLAN_DUPLICATE",()->svc.createVlan(new CreateVlanCommand(org,site,200,null,"duplicate"),new IpamCommandContext(actor,corr,"duplicate segment","ipam-edge-0006")));
  var activeVlan=svc.changeVlanStatus(vlan.id(),1,IpamStatus.ACTIVE,new IpamCommandContext(actor,corr,"activate segment","ipam-edge-0007"));
  var parent=svc.createNetwork(new CreateNetworkCommand(org,sub,site,activeVrf.id(),activeVlan.id(),null,NetworkKind.BLOCK,"10.40.0.0/16",null,null),new IpamCommandContext(actor,corr,"create block","ipam-edge-0008"));
  parent=svc.changeNetworkStatus(parent.id(),1,IpamStatus.ACTIVE,new IpamCommandContext(actor,corr,"activate block","ipam-edge-0009"));
  final IpamNetwork parentNet=parent;
  expect("DDI_PARENT_CONTAINMENT",()->svc.createNetwork(new CreateNetworkCommand(org,sub,site,activeVrf.id(),activeVlan.id(),parentNet.id(),NetworkKind.SUBNET,"10.41.0.0/24",null,null),new IpamCommandContext(actor,corr,"bad child","ipam-edge-0010")));
  var subnet=svc.createNetwork(new CreateNetworkCommand(org,sub,site,activeVrf.id(),activeVlan.id(),parentNet.id(),NetworkKind.SUBNET,"10.40.1.0/24",null,null),new IpamCommandContext(actor,corr,"create child","ipam-edge-0011"));
  subnet=svc.changeNetworkStatus(subnet.id(),1,IpamStatus.ACTIVE,new IpamCommandContext(actor,corr,"activate child","ipam-edge-0012"));
  final IpamNetwork activeSubnet=subnet;
  expect("DDI_VRF_IN_USE",()->svc.changeVrfStatus(activeVrf.id(),2,IpamStatus.RETIRED,new IpamCommandContext(actor,corr,"retire used vrf","ipam-edge-0013")));
  expect("DDI_POOL_RANGE_INVALID",()->svc.createPool(new CreatePoolCommand(org,activeSubnet.id(),"10.40.1.20","10.40.1.10","bad"),new IpamCommandContext(actor,corr,"bad range","ipam-edge-0014")));
  var pool=svc.createPool(new CreatePoolCommand(org,activeSubnet.id(),"10.40.1.10","10.40.1.10","single"),new IpamCommandContext(actor,corr,"single pool","ipam-edge-0015"));
  expect("DDI_POOL_OVERLAP",()->svc.createPool(new CreatePoolCommand(org,activeSubnet.id(),"10.40.1.10","10.40.1.11","overlap"),new IpamCommandContext(actor,corr,"overlap pool","ipam-edge-0016")));
  expect("DDI_POOL_REQUIRED",()->svc.allocate(new AllocateAddressCommand(org,activeVrf.id(),activeSubnet.id(),null,null,false,null,null,null,null),new IpamCommandContext(actor,corr,"missing pool","ipam-edge-0017")));
  var allocation=svc.allocate(new AllocateAddressCommand(org,activeVrf.id(),activeSubnet.id(),pool.id(),null,false,null,null,null,null),new IpamCommandContext(actor,corr,"allocate only ip","ipam-edge-0018"));
  expect("DDI_POOL_EXHAUSTED",()->svc.allocate(new AllocateAddressCommand(org,activeVrf.id(),activeSubnet.id(),pool.id(),null,false,null,null,null,null),new IpamCommandContext(actor,corr,"exhaust pool","ipam-edge-0019")));
  expect("DDI_ADDRESS_OUTSIDE_RANGE",()->svc.allocate(new AllocateAddressCommand(org,activeVrf.id(),activeSubnet.id(),pool.id(),"10.40.1.20",false,null,null,null,null),new IpamCommandContext(actor,corr,"outside pool","ipam-edge-0020")));
  expect("VERSION_CONFLICT",()->svc.release(allocation.id(),2,new IpamCommandContext(actor,corr,"stale release","ipam-edge-0021")));
  expect("DDI_NETWORK_IN_USE",()->svc.changeNetworkStatus(activeSubnet.id(),2,IpamStatus.RETIRED,new IpamCommandContext(actor,corr,"retire used subnet","ipam-edge-0022")));
  assertThrows(IpamNotFoundException.class,()->svc.address(ids.next()));
  assertThrows(IllegalArgumentException.class,()->svc.vrfs(org,0));
  assertThrows(IllegalArgumentException.class,()->svc.vlans(org,501));
  require(svc.vrf(activeVrf.id()).id().equals(activeVrf.id()),"get VRF");require(svc.vlan(activeVlan.id()).id().equals(activeVlan.id()),"get VLAN");require(svc.network(activeSubnet.id()).id().equals(activeSubnet.id()),"get network");
  require(!svc.pools(activeSubnet.id(),10).isEmpty(),"list pools");require(!svc.networks(org,activeVrf.id(),10).isEmpty(),"list networks");require(!svc.addresses(org,activeVrf.id(),activeSubnet.id(),10).isEmpty(),"list addresses");
 }
 @Test void replayPaginationScopeAndQuotaBranches(){
  var repo=new Repo();var idem=new Idem();var events=new InMemoryEventStore();var ids=new UuidV7Generator(CLOCK,new SecureRandom(new byte[]{7,7,7,7}));
  var org=ids.next();var sub=ids.next();var site=ids.next();var rsot=ids.next();var equipment=ids.next();var actor=ids.next();var corr=ids.next();
  var refs=new Refs(org,sub,site,rsot,equipment);var svc=new IpamApplicationService(repo,idem,new Features(true),refs,events,ids,CLOCK);
  var vrfCtx=new IpamCommandContext(actor,corr,"create vrf","ipam-replay-0001");var vrf=svc.createVrf(new CreateVrfCommand(org,"R1","Routing one",null),vrfCtx);require(svc.createVrf(new CreateVrfCommand(org,"R1","Routing one",null),vrfCtx).id().equals(vrf.id()),"vrf replay");
  vrf=svc.changeVrfStatus(vrf.id(),1,IpamStatus.ACTIVE,new IpamCommandContext(actor,corr,"activate vrf","ipam-replay-0002"));final IpamVrf activeVrf=vrf;
  require(svc.changeVrfStatus(vrf.id(),1,IpamStatus.ACTIVE,new IpamCommandContext(actor,corr,"activate vrf","ipam-replay-0002")).id().equals(vrf.id()),"vrf status replay");
  var vlanCtx=new IpamCommandContext(actor,corr,"create vlan","ipam-replay-0003");var vlan=svc.createVlan(new CreateVlanCommand(org,site,300,null,"v300"),vlanCtx);require(svc.createVlan(new CreateVlanCommand(org,site,300,null,"v300"),vlanCtx).id().equals(vlan.id()),"vlan replay");vlan=svc.changeVlanStatus(vlan.id(),1,IpamStatus.ACTIVE,new IpamCommandContext(actor,corr,"activate vlan","ipam-replay-0004"));final IpamVlan activeVlan=vlan;
  var netCtx=new IpamCommandContext(actor,corr,"create subnet","ipam-replay-0005");var net=svc.createNetwork(new CreateNetworkCommand(org,sub,site,activeVrf.id(),activeVlan.id(),null,NetworkKind.SUBNET,"192.0.2.0/29","test","trusted"),netCtx);require(svc.createNetwork(new CreateNetworkCommand(org,sub,site,activeVrf.id(),activeVlan.id(),null,NetworkKind.SUBNET,"192.0.2.0/29","test","trusted"),netCtx).id().equals(net.id()),"network replay");net=svc.changeNetworkStatus(net.id(),1,IpamStatus.ACTIVE,new IpamCommandContext(actor,corr,"activate subnet","ipam-replay-0006"));final IpamNetwork activeNet=net;
  var updateCtx=new IpamCommandContext(actor,corr,"update subnet","ipam-replay-0007");var updated=svc.updateNetwork(activeNet.id(),2,new UpdateNetworkCommand(activeVlan.id(),"updated","trusted"),updateCtx);require(svc.updateNetwork(activeNet.id(),2,new UpdateNetworkCommand(activeVlan.id(),"updated","trusted"),updateCtx).id().equals(updated.id()),"network update replay");
  var poolCtx=new IpamCommandContext(actor,corr,"create pool","ipam-replay-0008");var pool=svc.createPool(new CreatePoolCommand(org,activeNet.id(),"192.0.2.1","192.0.2.3","dynamic"),poolCtx);require(svc.createPool(new CreatePoolCommand(org,activeNet.id(),"192.0.2.1","192.0.2.3","dynamic"),poolCtx).id().equals(pool.id()),"pool replay");
  var allocationCtx=new IpamCommandContext(actor,corr,"allocate explicit","ipam-replay-0009");var address=svc.allocate(new AllocateAddressCommand(org,activeVrf.id(),activeNet.id(),pool.id(),"192.0.2.2",false,"host",rsot,equipment,"test"),allocationCtx);require(svc.allocate(new AllocateAddressCommand(org,activeVrf.id(),activeNet.id(),pool.id(),"192.0.2.2",false,"host",rsot,equipment,"test"),allocationCtx).id().equals(address.id()),"address replay");
  var releaseCtx=new IpamCommandContext(actor,corr,"release address","ipam-replay-0010");var released=svc.release(address.id(),1,releaseCtx);require(svc.release(address.id(),1,releaseCtx).id().equals(released.id()),"release replay");
  require(svc.vrfs(org,null,1).items().size()==1,"vrf cursor terminal");require(svc.vlans(org,null,1).items().size()==1,"vlan cursor terminal");require(svc.networks(org,activeVrf.id(),null,1).items().size()==1,"network cursor terminal");require(svc.pools(activeNet.id(),null,1).items().size()==1,"pool cursor terminal");
  assertThrows(IpamNotFoundException.class,()->svc.vrf(ids.next()));assertThrows(IpamNotFoundException.class,()->svc.vlan(ids.next()));assertThrows(IpamNotFoundException.class,()->svc.network(ids.next()));
  IpamFeaturePolicy zero=new IpamFeaturePolicy(){public boolean ipamEnabled(){return true;}public long vrfLimit(){return 0;}public long vlanLimit(){return 0;}public long prefixLimit(){return 0;}public long addressLimit(){return 0;}};
  var q1=new IpamApplicationService(new Repo(),new Idem(),zero,refs,new InMemoryEventStore(),ids,CLOCK);expect("DDI_VRF_QUOTA",()->q1.createVrf(new CreateVrfCommand(org,"Q","Quota",null),new IpamCommandContext(actor,corr,"quota vrf","ipam-quota-0001")));
  var qrepo=new Repo();var qidem=new Idem();IpamFeaturePolicy vlanZero=new IpamFeaturePolicy(){public boolean ipamEnabled(){return true;}public long vrfLimit(){return 10;}public long vlanLimit(){return 0;}public long prefixLimit(){return 10;}public long addressLimit(){return 10;}};var q2=new IpamApplicationService(qrepo,qidem,vlanZero,refs,new InMemoryEventStore(),ids,CLOCK);expect("DDI_VLAN_QUOTA",()->q2.createVlan(new CreateVlanCommand(org,site,10,null,"q"),new IpamCommandContext(actor,corr,"quota vlan","ipam-quota-0002")));
 }
 private record Features(boolean enabled) implements IpamFeaturePolicy{public boolean ipamEnabled(){return enabled;}public long vrfLimit(){return 50;}public long vlanLimit(){return 50;}public long prefixLimit(){return 100;}public long addressLimit(){return 1000;}}
 private record Refs(DomainIdentifier org,DomainIdentifier sub,DomainIdentifier site,DomainIdentifier rsot,DomainIdentifier equipment) implements IpamReferencePolicy{public void requireOrganization(DomainIdentifier o){if(!org.equals(o))throw new IpamConflictException("DDI_SCOPE_MISMATCH","org");}public void requireSubdivisionIfPresent(DomainIdentifier o,DomainIdentifier s){requireOrganization(o);if(s!=null&&!sub.equals(s))throw new IpamConflictException("DDI_SCOPE_MISMATCH","sub");}public void requireSiteIfPresent(DomainIdentifier o,DomainIdentifier s,DomainIdentifier x){requireSubdivisionIfPresent(o,s);if(x!=null&&!site.equals(x))throw new IpamConflictException("DDI_SITE_INVALID","site");}public void requireRsotIfPresent(DomainIdentifier o,DomainIdentifier x){requireOrganization(o);if(x!=null&&!rsot.equals(x))throw new IpamConflictException("DDI_RSOT_INVALID","rsot");}public void requireDcimEquipmentIfPresent(DomainIdentifier o,DomainIdentifier x){requireOrganization(o);if(x!=null&&!equipment.equals(x))throw new IpamConflictException("DDI_DCIM_INVALID","equipment");}}
 private static final class Idem implements IpamIdempotencyRepository{final Map<String,Record> m=new HashMap<>();public Optional<Record> find(String k){return Optional.ofNullable(m.get(k));}public void insert(Record r){if(m.putIfAbsent(r.key(),r)!=null)throw new IllegalStateException("duplicate idem");}}
 private static final class Repo implements IpamRepository{final Map<DomainIdentifier,IpamVrf> vrfs=new LinkedHashMap<>();final Map<DomainIdentifier,IpamVlan> vlans=new LinkedHashMap<>();final Map<DomainIdentifier,IpamNetwork> nets=new LinkedHashMap<>();final Map<DomainIdentifier,IpamPool> pools=new LinkedHashMap<>();final Map<DomainIdentifier,IpamAddress> addrs=new LinkedHashMap<>();int routingLocks,poolLocks;public long countVrfs(){return vrfs.size();}public long countVlans(){return vlans.size();}public long countNetworks(){return nets.size();}public long countAddresses(){return addrs.size();}public void lockRoutingEnvironment(DomainIdentifier o,DomainIdentifier v){routingLocks++;}public void lockPool(DomainIdentifier p){poolLocks++;}public boolean vrfCodeExists(DomainIdentifier o,String c){return vrfs.values().stream().anyMatch(x->x.organizationId().equals(o)&&x.code().equalsIgnoreCase(c));}public boolean hasActiveNetworks(DomainIdentifier v){return nets.values().stream().anyMatch(x->x.vrfId().equals(v)&&x.status()!=IpamStatus.RETIRED);}public boolean hasActiveNetworksForVlan(DomainIdentifier v){return nets.values().stream().anyMatch(x->v.equals(x.vlanId())&&x.status()!=IpamStatus.RETIRED);}public boolean vlanExists(DomainIdentifier o,Integer v,Long n){return vlans.values().stream().anyMatch(x->x.organizationId().equals(o)&&x.status()!=IpamStatus.RETIRED&&((v!=null&&v.equals(x.vlanId()))||(n!=null&&n.equals(x.vni()))));}public boolean networkOverlaps(DomainIdentifier o,DomainIdentifier v,IpCidr c,DomainIdentifier ex){return nets.values().stream().anyMatch(x->x.organizationId().equals(o)&&x.vrfId().equals(v)&&(ex==null||!x.id().equals(ex))&&x.status()!=IpamStatus.RETIRED&&x.cidr().overlaps(c));}public boolean addressInUse(DomainIdentifier v,String a){String c=IpCidr.canonicalAddress(a);return addrs.values().stream().anyMatch(x->x.vrfId().equals(v)&&x.address().equals(c)&&x.status()!=AddressStatus.RELEASED);}public boolean poolOverlaps(DomainIdentifier n,String a,String b){return pools.values().stream().filter(x->x.networkId().equals(n)&&x.status()!=IpamStatus.RETIRED).anyMatch(x->IpCidr.sortKey(a).compareTo(IpCidr.sortKey(x.endAddress()))<=0&&IpCidr.sortKey(x.startAddress()).compareTo(IpCidr.sortKey(b))<=0);}public Optional<IpamVrf> vrf(DomainIdentifier id){return Optional.ofNullable(vrfs.get(id));}public Optional<IpamVlan> vlan(DomainIdentifier id){return Optional.ofNullable(vlans.get(id));}public Optional<IpamNetwork> network(DomainIdentifier id){return Optional.ofNullable(nets.get(id));}public Optional<IpamPool> pool(DomainIdentifier id){return Optional.ofNullable(pools.get(id));}public Optional<IpamAddress> address(DomainIdentifier id){return Optional.ofNullable(addrs.get(id));}public List<IpamVrf> vrfs(DomainIdentifier o,DomainIdentifier after,int l){return vrfs.values().stream().filter(x->x.organizationId().equals(o)&&(after==null||x.id().compareTo(after)>0)).sorted(Comparator.comparing(IpamVrf::id)).limit(l).toList();}public List<IpamVlan> vlans(DomainIdentifier o,DomainIdentifier after,int l){return vlans.values().stream().filter(x->x.organizationId().equals(o)&&(after==null||x.id().compareTo(after)>0)).sorted(Comparator.comparing(IpamVlan::id)).limit(l).toList();}public List<IpamNetwork> networks(DomainIdentifier o,DomainIdentifier v,DomainIdentifier after,int l){return nets.values().stream().filter(x->x.organizationId().equals(o)&&(v==null||x.vrfId().equals(v))&&(after==null||x.id().compareTo(after)>0)).sorted(Comparator.comparing(IpamNetwork::id)).limit(l).toList();}public List<IpamPool> pools(DomainIdentifier n,DomainIdentifier after,int l){return pools.values().stream().filter(x->x.networkId().equals(n)&&(after==null||x.id().compareTo(after)>0)).sorted(Comparator.comparing(IpamPool::id)).limit(l).toList();}public List<IpamAddress> addresses(DomainIdentifier o,DomainIdentifier v,DomainIdentifier n,DomainIdentifier after,int l){return addrs.values().stream().filter(x->x.organizationId().equals(o)&&(v==null||x.vrfId().equals(v))&&(n==null||x.networkId().equals(n))&&(after==null||x.id().compareTo(after)>0)).sorted(Comparator.comparing(IpamAddress::id)).limit(l).toList();}public void insertVrf(IpamVrf x){vrfs.put(x.id(),x);}public void updateVrf(IpamVrf x,long v){check(vrfs.get(x.id()).version(),v);vrfs.put(x.id(),x);}public void insertVlan(IpamVlan x){vlans.put(x.id(),x);}public void updateVlan(IpamVlan x,long v){check(vlans.get(x.id()).version(),v);vlans.put(x.id(),x);}public void insertNetwork(IpamNetwork x){nets.put(x.id(),x);}public void updateNetwork(IpamNetwork x,long v){check(nets.get(x.id()).version(),v);nets.put(x.id(),x);}public void insertPool(IpamPool x){pools.put(x.id(),x);}public void updatePool(IpamPool x,long v){check(pools.get(x.id()).version(),v);pools.put(x.id(),x);}public void insertAddress(IpamAddress x){addrs.put(x.id(),x);}public void updateAddress(IpamAddress x,long v){check(addrs.get(x.id()).version(),v);addrs.put(x.id(),x);}private static void check(long a,long b){if(a!=b)throw new IpamConflictException("VERSION_CONFLICT","version");}}
 private static void expect(String code,Action a){try{a.run();}catch(IpamConflictException e){require(code.equals(e.code()),"unexpected code "+e.code());return;}catch(Exception e){throw new AssertionError(e);}throw new AssertionError("expected "+code);}private static void require(boolean c,String m){if(!c)throw new AssertionError(m);}@FunctionalInterface interface Action{void run()throws Exception;}
}
